void stage(VuState &vu) {
    float (*vf)[4] = vu.vf;
    int32_t *vi = vu.vi;
    uint32_t &mac = vu.mac;

    // 0x448
    // ADDq.z vf6, vf0, Q
    vf[6][Z] = vu.q;
    // MOVE.xy vf19, vf21
    vf[19][X] = vf[21][X];
    vf[19][Y] = vf[21][Y];

    // 0x450
    // SUB.yz vf0, vf23, vf15
    {
        float dy = vf[23][Y] - vf[15][Y];
        float dz = vf[23][Z] - vf[15][Z];
        mac &= ~(0x44 | 0x22);
        mac |= ((dy == 0.0f) ? 4 : 0) | ((dy < 0.0f) ? 0x40 : 0);
        mac |= ((dz == 0.0f) ? 2 : 0) | ((dz < 0.0f) ? 0x20 : 0);
    }
    // IADDIU vi12, vi0, 6
    vi[12] = int32_t(int16_t(vi[0] + 6));

    // 0x458
    // ADDw.z vf19, vf21, vf27w
    vf[19][Z] = vf[21][Z] + vf[27][W];
    // NOP

    // 0x460
    // MAXw.xy vf7, vf7, vf31w
    { float b = vf[31][W]; vf[7][X] = std::max(vf[7][X], b); vf[7][Y] = std::max(vf[7][Y], b); }
    // DIV Q, vf0w, vf18w
    vu.q = 1.0f / vf[18][W];

    // 0x468
    // ADD.xz vf21, vf21, vf31
    vf[21][X] += vf[31][X];
    vf[21][Z] += vf[31][Z];
    // MTIR vi10, vf13w
    { uint32_t v; std::memcpy(&v, &vf[13][W], 4); vi[10] = int32_t(int16_t(v)); }

    // 0x470
    // MUL.xy vf6, vf6, vf12
    vf[6][X] *= vf[12][X];
    vf[6][Y] *= vf[12][Y];
    // FMAND vi6, vi12 [MAC flags of the upper instruction at 0x450]
    vi[6] = mac & vi[12];
    // Update MAC for MUL.xy (not read by FMAND, but maintains architectural correctness)
    {
        mac &= ~(0x88 | 0x44);
        mac |= ((vf[6][X] == 0.0f) ? 8 : 0) | ((vf[6][X] < 0.0f) ? 0x80 : 0);
        mac |= ((vf[6][Y] == 0.0f) ? 4 : 0) | ((vf[6][Y] < 0.0f) ? 0x40 : 0);
    }

    // 0x478
    // SUBz.x vf8, vf25, vf20z
    vf[8][X] = vf[25][X] - vf[20][Z];
    // SQ.xyz vf19, 14(vi8)
    sq(vu, vf[19], vi[8] + 14, 0x7);

    // 0x480
    // ADDw.y vf8, vf0, vf28w
    vf[8][Y] = vf[28][W];
    // SQ.xyz vf19, 14(vi9)
    sq(vu, vf[19], vi[9] + 14, 0x7);

    // 0x488
    // MULAx.xyzw ACC, vf1, vf19x
    { float b = vf[19][X]; for(int c=0;c<4;++c) vu.acc[c] = vf[1][c] * b; }
    // ISUB vi6, vi12, vi6
    vi[6] = int32_t(int16_t(vi[12] - vi[6]));

    // 0x490
    // MADDAy.xyzw ACC, vf2, vf19y
    { float b = vf[19][Y]; for(int c=0;c<4;++c) vu.acc[c] += vf[2][c] * b; }
    // SQ.xyz vf6, 0(vi8)
    sq(vu, vf[6], vi[8] + 0, 0x7);

    // 0x498
    // MADDAz.xyzw ACC, vf3, vf19z
    { float b = vf[19][Z]; for(int c=0;c<4;++c) vu.acc[c] += vf[3][c] * b; }
    // SQ.xyz vf6, 0(vi9)
    sq(vu, vf[6], vi[9] + 0, 0x7);

    vu.pc = 0x4a0;
}
