    {
        lq(vu, vf[11], vi[1] + 49);
    }

    // 0a20
    // ADDz.x vf6, vf0, vf6z
    {
        vf[6][X] = vf[0][X] + vf[6][Z];
    }
    // DIV Q, vf0w, vf16w
    {
        vu.q = vf[0][W] / vf[16][W];
    }

    // 0a28
    // ADD.y vf6, vf0, vf28
    {
        vf[6][Y] = vf[0][Y] + vf[28][Y];
    }
    // ISW.w vi10, 2(vi2)
    {
        isw(vu, vi[2] + 2, W, vi[10]);
    }

    // 0a30
    // SUBy.w vf7, vf20, vf20y
    {
        vf[7][W] = vf[20][W] - vf[20][Y];
    }
    // ISW.w vi10, 2(vi7)
    {
        isw(vu, vi[7] + 2, W, vi[10]);
    }

    // 0a38
    // MULAx.xyzw ACC, vf1, vf17x
    {
        float mul = vf[17][X];
        vu.acc[X] = vf[1][X] * mul;
        vu.acc[Y] = vf[1][Y] * mul;
        vu.acc[Z] = vf[1][Z] * mul;
        vu.acc[W] = vf[1][W] * mul;
        update_mac(vu.acc, vu.mac, true, true, true, true);
    }
