    vf[5][X] = vu.acc[X] + vf[29][X] * vf[0][W];
    vf[5][Y] = vu.acc[Y] + vf[29][Y] * vf[0][W];
    update_mac(vu, vf[5], 0x3);
    vf[18][X] = vf[21][X];
    vf[18][Y] = vf[21][Y];

    // 0a78
    vf[16][X] *= vu.q;
    vf[16][Y] *= vu.q;
    vf[16][Z] *= vu.q;
    update_mac(vu, vf[16], 0x7);
    store_qword(vu, vi[9] + 7, vf[11]);

    // 0a80
    vf[5][Z] = vu.q;
    update_mac(vu, vf[5], 0x4);
    store_qword(vu, vi[8] + 13, vf[11]);

    // 0a88
    vf[18][Z] = vf[21][Z] + vf[27][Z];
    update_mac(vu, vf[18], 0x4);
    store_qword(vu, vi[9] + 13, vf[11]);

    // 0a90
    vf[6][X] = std::max(vf[6][X], vf[31][W]);
    vf[6][Y] = std::max(vf[6][Y], vf[31][W]);
    update_mac(vu, vf[6], 0x3);
    vu.q = 1.0f / vf[17][W];

