    update_mac(vu, vf[5], 0x3);
    store_word(vu, vi[9] + 2, 3, vi[12]);

    // 0ab0
    vf[7][X] = vf[7][W];
    update_mac(vu, vf[7], 0x1);

    // 0ab8
    vf[7][Y] = vf[28][Z];
    update_mac(vu, vf[7], 0x2);
    vi[10] = low16(vf[13][Z]);

    // 0ac0
    vu.acc[X] = vf[1][X] * vf[18][X];
    vu.acc[Y] = vf[1][Y] * vf[18][X];
    vu.acc[Z] = vf[1][Z] * vf[18][X];
    vu.acc[W] = vf[1][W] * vf[18][X];
    update_mac(vu, vu.acc, 0xF);

    // 0ac8
    vf[5][X] *= vf[5][Z];
    vf[5][Y] *= vf[5][Z];
    update_mac(vu, vf[5], 0x3);

    // 0ad0
    vu.acc[X] += vf[2][X] * vf[18][Y];
    vu.acc[Y] += vf[2][Y] * vf[18][Y];
    vu.acc[Z] += vf[2][Z] * vf[18][Y];
    vu.acc[W] += vf[2][W] * vf[18][Y];
    update_mac(vu, vu.acc, 0xF);
    store_qword_masked(vu, vi[2] + 2, vf[16], 0x7);

    // 0ad8
    vu.acc[X] += vf[3][X] * vf[18][Z];
    vu.acc[Y] += vf[3][Y] * vf[18][Z];
    vu.acc[Z] += vf[3][Z] * vf[18][Z];
    vu.acc[W] += vf[3][W] * vf[18][Z];
    update_mac(vu, vu.acc, 0xF);
    store_qword_masked(vu, vi[7] + 2, vf[16], 0x7);

    // 0ae0
    vf[7][X] = std::min(vf[7][X], vu.i);
    vf[7][Y] = std::min(vf[7][Y], vu.i);
    update_mac(vu, vf[7], 0x3);
    store_word(vu, vi[8] + 8, 3, vi[10]);

    vu.pc = 0xae8;
