void stage(VuState &vu) {
    uint32_t clip = vu.clip & 0xFFFFFF;
    int32_t *vi = vu.vi;

    // 1a10: FCOR vi1, 0xfdf7df
    vi[1] = ((clip | 0xfdf7df) == 0xFFFFFF) ? 1 : 0;
    // 1a18: IBNE vi1, vi0, 0x1b18
    if (vi[1] != 0) { vu.pc = 0x1b18; goto delay_slot_1a18; }

    // 1a28: FCOR vi1, 0xffdf7d
    vi[1] = ((clip | 0xffdf7d) == 0xFFFFFF) ? 1 : 0;
    // 1a30: IBNE vi1, vi0, 0x1b18
    if (vi[1] != 0) { vu.pc = 0x1b18; goto delay_slot_1a30; }

    // 1a38: IAND vi8, vi12, vi9
    vi[8] = vi16(vi[12] & vi[9]);

    // 1a40: FCOR vi1, 0xffefbe
    vi[1] = ((clip | 0xffefbe) == 0xFFFFFF) ? 1 : 0;
    // 1a48: IBNE vi1, vi0, 0x1b18
    if (vi[1] != 0) { vu.pc = 0x1b18; goto delay_slot_1a48; }

    // 1a58: IBNE vi8, vi0, 0x1b18
    if (vi[8] != 0) { vu.pc = 0x1b18; goto delay_slot_1a58; }

    // 1a68: FCAND vi1, 0x010410
    vi[1] = ((clip & 0x010410) != 0) ? 1 : 0;
    // 1a70: IBNE vi1, vi0, 0x1b18
    if (vi[1] != 0) { vu.pc = 0x1b18; goto delay_slot_1a70; }

    // 1a80: FCOR vi1, 0xff7df7
    vi[1] = ((clip | 0xff7df7) == 0xFFFFFF) ? 1 : 0;
    // 1a88: IBNE vi1, vi0, 0x1b18
    if (vi[1] != 0) { vu.pc = 0x1b18; goto delay_slot_1a88; }

    // 1a98: FCOR vi1, 0xffbefb
    vi[1] = ((clip | 0xffbefb) == 0xFFFFFF) ? 1 : 0;
    // 1aa0: IBNE vi1, vi0, 0x1b18
    if (vi[1] != 0) { vu.pc = 0x1b18; goto delay_slot_1aa0; }

    // 1ab0: FCAND vi1, 0x020820
    vi[1] = ((clip & 0x020820) != 0) ? 1 : 0;
    // 1ab8: IBNE vi1, vi0, 0x1ae8
    if (vi[1] != 0) { vu.pc = 0x1ae8; return; }

    // 1ac8: BAL vi15, 0x2550
    // vi15 = (address of pair after delay slot) / 8 = 0x1ad8 / 8 = 859
    vi[15] = 859;
    vu.pc = 0x2550;
    return;

// Delay slots for branches to 1b18
delay_slot_1a18:
    // 1a20: NOP
    goto handle_1b18;

delay_slot_1a30:
    // 1a38: IAND vi8, vi12, vi9
    vi[8] = vi16(vi[12] & vi[9]);
    goto handle_1b18;

delay_slot_1a48:
    // 1a50: NOP
    goto handle_1b18;

delay_slot_1a58:
    // 1a60: NOP
    goto handle_1b18;

delay_slot_1a70:
    // 1a78: NOP
    goto handle_1b18;

delay_slot_1a88:
    // 1a90: NOP
    goto handle_1b18;

delay_slot_1aa0:
    // 1aa8: NOP
    goto handle_1b18;

handle_1b18:
    // 1b18: B 0x19f0
    // 1b20: ISW.w vi12, 0(vi2)
    uint32_t addr = vi[2] & 0x3FF;
    uint16_t val = vi[12] & 0xFFFF;
    std::memcpy(&vu.mem[16 * addr + 12], &val, 2);
    vu.pc = 0x19f0;
    return;
}
