    vu.q = vf[0][W] / vf[16][W];

    // 0x1c20 MULAx.xyzw ACC, vf1, vf17x | NOP
    for (int c = 0; c < 4; ++c) vu.acc[c] = vf[1][c] * vf[17][X];

